Ces objets sont des robes, des v&#234;tements et tous les objets port&#233;s sur le corps ou autour.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; sur le corps &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 500 g et 2,5 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur le corps&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Corde-Infinie.html&quot; title=&quot;Robe de corde infinie&quot;&gt;Robe de corde infinie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de cr&#233;er de longues lignes de ficelle ou de corde &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-La-Manticore.html&quot; title=&quot;Robe de la manticore&quot;&gt;Robe de la manticore&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut projeter des piques &#224; distance qui font saigner leurs cibles.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Du-Ma&#238;tre-Des-Ma&#238;tres.html&quot; title=&quot;Robe du ma&#238;tre des ma&#238;tres&quot;&gt;Robe du ma&#238;tre des ma&#238;tres&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (danse). Un suivant du dieu du savoir peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/i&gt; (1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;) une fois par jour, et soigner 1 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;point de vie&lt;/a&gt; &#224; 7 cr&#233;atures au maximum autour de lui.&lt;/td&gt;&lt;td&gt;2 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Dossements.html&quot; title=&quot;Robe d&amp;#39;ossements&quot;&gt;Robe d’ossements&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de convoquer jusqu’&#224; 12 &lt;a class=&quot;pagelink&quot; href=&quot;Zombi,-Arch&#233;type.html&quot; title=&quot;Zombi, arch&#233;type&quot;&gt;zombies&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Squelette,-Arch&#233;type.html&quot; title=&quot;Squelette, arch&#233;type&quot;&gt;squelettes&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandelettes-De-Frappes-D&#233;vastatrices.html&quot; title=&quot;Bandelettes de frappes d&#233;vastatrices&quot;&gt;Bandelettes de frappes d&#233;vastatrices&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration aux jets d’attaque et de d&#233;g&#226;ts et/ou une propri&#233;t&#233; sp&#233;ciale &#224; une (ou plus) attaque &#224; mains nues ou naturelle, &#224; chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 48 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 75 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 108 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +7&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +7.&lt;/td&gt;&lt;td&gt;| 147 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corset-Vishkanyan.html&quot; title=&quot;Corset vishkanyan&quot;&gt;Corset vishkanyan&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 rounds par jour, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Compression.html&quot; title=&quot;Compression&quot;&gt;compression&lt;/a&gt;&lt;/i&gt; et un bonus de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oripeaux-De-La-Sorci&#232;re.html&quot; title=&quot;Oripeaux de la sorci&#232;re&quot;&gt;Oripeaux de la sorci&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Un suivant de la d&#233;esse-guenaude de la haine peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;d&#233;tection des pens&#233;es&quot;&gt;d&#233;tection des pens&#233;es&lt;/a&gt;&lt;/i&gt; une fois par jour.&lt;/td&gt;&lt;td&gt;3 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasuble-De-Druide.html&quot; title=&quot;Chasuble de druide&quot;&gt;Chasuble de druide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Si le porteur poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#FORMEANIMALE&quot; title=&quot;Le druide&quot;&gt;forme animale&lt;/a&gt;, il peut l’utiliser une fois de plus par jour.&lt;/td&gt;&lt;td&gt;3 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soutane-De-Pr&#234;tre.html&quot; title=&quot;Soutane de pr&#234;tre&quot;&gt;Soutane de pr&#234;tre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +3 aux tests associ&#233;s au &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; pour influencer les cr&#233;atures poss&#233;dant le m&#234;me alignement ou la m&#234;me divinit&#233; tut&#233;laire que le porteur. Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanctuaire.html&quot; title=&quot;Sanctuaire&quot;&gt;sanctuaire&lt;/a&gt;&lt;/i&gt; une fois par jour chacun. Conf&#232;re une oraison suppl&#233;mentaire, et permet d’en apprendre une de plus par jour. Fait office de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;focalisateur divin&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;4 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Densorceleur.html&quot; title=&quot;Robe d’ensorceleur&quot;&gt;Robe d’ensorceleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, un &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;ensorceleur&lt;/a&gt; peut d&#233;clencher les effets de son pouvoir de lignage de niveau 1 sur la cible d’un sort qu’il lance.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Composantes.html&quot; title=&quot;Robe de composantes&quot;&gt;Robe de composantes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fait office de &lt;a class=&quot;pagelink&quot; href=&quot;Sacoche-&#192;-Composantes-(Objet).html&quot; title=&quot;Sacoche &#224; composantes&quot;&gt;sacoche &#224; composantes&lt;/a&gt;, mais peut &#233;galement fournir des &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;composantes mat&#233;rielles&lt;/a&gt; valant 50 po ou moins.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-M&#233;morisation.html&quot; title=&quot;Robe de m&#233;morisation&quot;&gt;Robe de m&#233;morisation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, un lanceur de sorts spontan&#233;s peut d&#233;penser un emplacement de sort pour incanter un sort &#233;crit qu’il est capable de lire comme s’il le connaissait.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;V&#234;tements-Vivants.html&quot; title=&quot;V&#234;tements vivants&quot;&gt;V&#234;tements vivants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;. S’ajuste en fonction de l’humeur que veut faire passer le porteur.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Harnais-Dancrage-Pour-Eidolon.html&quot; title=&quot;Harnais d’ancrage pour eidolon&quot;&gt;Harnais d’ancrage pour eidolon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html#EIDOLON&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;eidolon&lt;/a&gt; peut consommer les utilisations de &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html#CONVOCATIONDEMONSTRES&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;convocation de monstres&lt;/a&gt; de son &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;conjurateur&lt;/a&gt; pour rester sur le Plan Mat&#233;riel quand il devrait en &#234;tre chass&#233; &#224; cause de l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Inconscient&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;inconscience&lt;/a&gt; de ce dernier.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Lupine.html&quot; title=&quot;Robe lupine&quot;&gt;Robe lupine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quatre fois par jour, permet d&#39;ajouter 1d6 au r&#233;sultat d&#39;un test de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; bas&#233; sur la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;, l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; ou le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Kitsune-(Race).html&quot; title=&quot;Les kitsune&quot;&gt;kitsune&lt;/a&gt; peut d&#233;penser deux utilisations quotidiennes pour ajouter 1d10 &#224; la place.&lt;/td&gt;&lt;td&gt;6 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Camelot.html&quot; title=&quot;Robe de camelot&quot;&gt;Robe de camelot&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, le porteur peut d&#233;tacher plusieurs outils de cette robe (cordes de chanvre (15 m), dagues, lanternes sourdes (pleine), miroirs, perches (3 m), sacs).&lt;/td&gt;&lt;td&gt;7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-D&#233;claireur.html&quot; title=&quot;Manteau d&amp;#39;&#201;claireur&quot;&gt;Manteau d&#39;&#201;claireur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, le porteur peut manifester un &#233;quipement parmi une liste limit&#233;e.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Mim&#233;tisme.html&quot; title=&quot;Robe de mim&#233;tisme&quot;&gt;Robe de mim&#233;tisme&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; une heure par jour, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Modification-Dapparence.html&quot; title=&quot;Modification d&amp;#39;apparence&quot;&gt;modification d’apparence&lt;/a&gt;&lt;/i&gt;, tout en lui apprenant la langue de la race dont il prend la forme.&lt;/td&gt;&lt;td&gt;8 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Ardente.html&quot; title=&quot;Robe ardente&quot;&gt;Robe ardente&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une r&#233;sistance au feu de 5 et augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; du porteur de +1 pour les sorts du registre du feu. Une fois par jour, peut &#233;mettre un rayonnement infligeant des d&#233;g&#226;ts de feu autour du porteur.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-&#201;lectrifi&#233;e.html&quot; title=&quot;Robe &#233;lectrifi&#233;e&quot;&gt;Robe &#233;lectrifi&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une r&#233;sistance &#224; l’&#233;lectricit&#233; de 5 et augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; du porteur de +1 pour les sorts du registre de l’&#233;lectricit&#233;. Une fois par jour, peut &#233;mettre un rayonnement infligeant des d&#233;g&#226;ts d’&#233;lectricit&#233; autour du porteur.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Gel&#233;e.html&quot; title=&quot;Robe gel&#233;e&quot;&gt;Robe gel&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une r&#233;sistance au froid de 5 et augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; du porteur de +1 pour les sorts du registre du froid. Une fois par jour, peut &#233;mettre un rayonnement infligeant des d&#233;g&#226;ts de froid autour du porteur.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Moine.html&quot; title=&quot;Robe de moine&quot;&gt;Robe de moine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; voit son niveau effectif de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; augment&#233; de 5 pour d&#233;terminer sa CA et ses d&#233;g&#226;ts. Un non-moine obtient ces bonus comme un moine de niveau 5. Conf&#232;re une utilisation du don &lt;a class=&quot;pagelink&quot; href=&quot;Coup-&#201;tourdissant.html&quot; title=&quot;Coup &#233;tourdissant&quot;&gt;Coup &#233;tourdissant&lt;/a&gt; de plus par jour si le porteur le poss&#232;de.&lt;/td&gt;&lt;td&gt;13 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Du-Tueur.html&quot; title=&quot;Robe du tueur&quot;&gt;Robe du tueur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; pour dissimuler une arme, ainsi qu’un bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; (Le bonus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; est &#233;gal &#224; celui de sa &lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html#CIBLEETUDIEE&quot; title=&quot;Le tueur&quot;&gt;cible &#233;tudi&#233;e&lt;/a&gt; pour un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html&quot; title=&quot;Le tueur&quot;&gt;tueur&lt;/a&gt;). Jusqu’&#224; 5 minutes par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tat-Gazeux.html&quot; title=&quot;&#201;tat gazeux&quot;&gt;&#233;tat gazeux&lt;/a&gt;&lt;/i&gt;, le bonus aux tests de Discr&#233;tion passe &#224; +10 tant que ce pouvoir est actif.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Lh&#233;ritage-Magique.html&quot; title=&quot;Robe de l’h&#233;ritage magique&quot;&gt;Robe de l&#39;h&#233;ritage magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;ensorceleur&lt;/a&gt; voit son niveau effectif d’&lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;ensorceleur&lt;/a&gt; augment&#233; de 4 pour d&#233;terminer les pouvoirs de lignage qu’il peut utiliser et leurs effets.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Du-Xorn.html&quot; title=&quot;Robe du xorn&quot;&gt;Robe du xorn&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et la capacit&#233; de &lt;a class=&quot;pagelink&quot; href=&quot;Nage-Dans-La-Terre-(Capacit&#233;).html&quot; title=&quot;Nage dans la terre (Ext)&quot;&gt;nage dans la terre&lt;/a&gt; (6 m). Le porteur peut se nourrir de min&#233;raux.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corset-De-Sorcellerie.html&quot; title=&quot;Corset de sorcellerie&quot;&gt;Corset de sorcellerie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’armure de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Une &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;re&lt;/a&gt; peut augmenter son &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; de +2 pour d&#233;terminer les effets d’un mal&#233;fice de sa connaissance toutes les 24 heures.&lt;/td&gt;&lt;td&gt;22 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Habit-De-La-Fausse-Foi.html&quot; title=&quot;Habit de la fausse foi&quot;&gt;Habit de la fausse foi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut imiter n&#39;importe quelle tenue c&#233;r&#233;monielle ou fonctionnelle d&#39;un religieux de n&#39;importe quelle foi, le porteur b&#233;n&#233;ficie alors d&#39;avantages pour se faire passer pour un membre de la foi imit&#233;e, pour utiliser des objets magiques associ&#233;s &#224; cette foi, et son alignement est trait&#233; comme &#233;tant celui de cette foi.&lt;/td&gt;&lt;td&gt;27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Prismatique.html&quot; title=&quot;Robe prismatique&quot;&gt;Robe prismatique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#H&#233;b&#233;t&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;h&#233;b&#233;ter&lt;/a&gt; les cr&#233;atures dans un rayon de 9 m du porteur pendant 1d4+1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;, pour chaque round d’h&#233;b&#233;tement, conf&#232;re +10&#160;% de camouflage. Fonctionne jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour. &lt;/td&gt;&lt;td&gt;27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cache-Poussi&#232;re-Du-Tireur.html&quot; title=&quot;Cache-poussi&#232;re du tireur&quot;&gt;Cache-poussi&#232;re du tireur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’armure de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et un bonus de chance de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les tirs d’armes &#224; feu. Un &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html&quot; title=&quot;Le pistolier&quot;&gt;pistolier&lt;/a&gt; (ou un porteur poss&#233;dant le don &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier-Amateur.html&quot; title=&quot;Pistolier amateur&quot;&gt;Pistolier amateur&lt;/a&gt;) obtient 1 point d’&lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html#AUDACE&quot; title=&quot;Le pistolier&quot;&gt;audace&lt;/a&gt; suppl&#233;mentaire par jour. Augmente le bonus de l’exploit &lt;a class=&quot;pagelink&quot; href=&quot;Exploits.html#ESQUIVEDUPISTOLIER&quot; title=&quot;Les exploits du pistolier&quot;&gt;esquive du pistolier&lt;/a&gt; de +1 et permet &#224; un non-pistolier d’utiliser cet exploit une fois par jour.&lt;/td&gt;&lt;td&gt;36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Contrebandier.html&quot; title=&quot;Robe de contrebandier&quot;&gt;Robe de contrebandier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur et ses objets peuvent &#234;tre absorb&#233;s dans un espace extra-dimensionnel &#224; l’int&#233;rieur de la robe jusqu’&#224; 24 heures sans probl&#232;mes, le porteur &#233;tant capable d’observer les alentours de la robe et d’en sortir &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;48 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-&#201;toil&#233;e.html&quot; title=&quot;Robe &#233;toil&#233;e&quot;&gt;Robe &#233;toil&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de chance de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt;. Permet de voyager entre le Plan Astral et le Plan Mat&#233;riel &#224; volont&#233; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Plan.html&quot; title=&quot;Changement de plan&quot;&gt;changement de plan&lt;/a&gt;&lt;/i&gt;). Une fois par mois, cette robe g&#233;n&#232;re 6 shurikens +5 que le porteur sait manier.&lt;/td&gt;&lt;td&gt;58 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Convocation.html&quot; title=&quot;Robe de convocation&quot;&gt;Robe de convocation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, quand le porteur lance un sort de convocation, il peut convoquer le nombre maximum de cr&#233;atures. Une fois par jour, un &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;conjurateur&lt;/a&gt; peut convoquer son &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html#EIDOLON&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;eidolon&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kimono-Mystique.html&quot; title=&quot;Kimono mystique&quot;&gt;Kimono mystique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; et un bonus de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt;. Une fois par jour, peut emprisonner une cr&#233;ature dans un espace exta-dimensionnel (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;dale.html&quot; title=&quot;D&#233;dale&quot;&gt;d&#233;dale&lt;/a&gt;&lt;/i&gt;), augmentant les bonus pr&#233;c&#233;dents de +2, jusqu’&#224; 10 minutes.&lt;/td&gt;&lt;td&gt;67 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Darchimage.html&quot; title=&quot;Robe d&amp;#39;archimage&quot;&gt;Robe d&#39;archimage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant que le porteur ne partage pas l’alignement de cette robe et que c’est un lanceur de sorts profanes, celle-ci conf&#232;re un bonus d’armure de +5 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt; de 18, un bonus de r&#233;sistance aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; de +4 et un bonus d’alt&#233;ration de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; pour vaincre la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;, et ce contre des &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;Absorption d’&#233;nergie (Sur)&quot;&gt;niveaux n&#233;gatifs&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;75 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Resplendissante-Du-Com&#233;dien.html&quot; title=&quot;Robe resplendissante du com&#233;dien&quot;&gt;Robe resplendissante du com&#233;dien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re aux &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;bardes&lt;/a&gt; une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt; de 18, un bonus de r&#233;sistance de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; et un bonus d’alt&#233;ration de +2 aux tests de NLS pour vaincre la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;75 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Voyage-Stellaire.html&quot; title=&quot;Robe de voyage stellaire&quot;&gt;Robe de voyage stellaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-Dadaptation.html&quot; title=&quot;Collier d&amp;#39;adaptation&quot;&gt;collier d&#39;adaptation&lt;/a&gt;&lt;/i&gt;. Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ailes-De-Vol.html&quot; title=&quot;Ailes de vol&quot;&gt;ailes de vol&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;, et de voyager dans le vide sid&#233;ral &#224; grande vitesse tout en prot&#233;geant le porteur.&lt;/td&gt;&lt;td&gt;82 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-Du-P&#233;nitent.html&quot; title=&quot;Robe du p&#233;nitent&quot;&gt;Robe du p&#233;nitent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt;. Au prix d&#39;utilisations de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le porteur peut faire des voeux sp&#233;ciaux pour b&#233;n&#233;ficier d&#39;avantages suppl&#233;mentaires.&lt;/td&gt;&lt;td&gt;95 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Robe-De-Vision-Totale.html&quot; title=&quot;Robe de vision totale&quot;&gt;Robe de vision totale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une vision &#224; 360&#176;, la vision dans le noir, et la vision des cr&#233;atures invisibles et &#233;th&#233;r&#233;es &#224; 36 m, un bonus de comp&#233;tence de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;. Immunise contre la perte du bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et contre la prise en tenaille. Rend vuln&#233;rable aux sorts de lumi&#232;re et aux attaques de regard.&lt;/td&gt;&lt;td&gt;120 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
